<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require __DIR__.'/core.php';
$dir=\NL\data_dir();if(is_file($dir.'/cms.sqlite')){fwrite(STDERR,"Данные уже установлены; существующая база не изменена.\n");exit(1);}
$hash=$argv[1]??'';if(!preg_match('/^[a-f0-9]{64}$/',$hash)){fwrite(STDERR,"Передайте SHA-256 одноразового ключа установки.\n");exit(1);}
if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new RuntimeException('Не удалось создать каталог данных.');chmod($dir,0700);
$pdo=\NL\db();$pdo->exec('CREATE TABLE documents(name TEXT PRIMARY KEY,value TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL); CREATE TABLE revisions(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,value TEXT NOT NULL,created_at TEXT NOT NULL); CREATE INDEX revision_name ON revisions(name,id); CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TEXT NOT NULL); CREATE TABLE attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,ip TEXT NOT NULL,attempted_at INTEGER NOT NULL); CREATE INDEX attempts_ip ON attempts(ip,attempted_at); CREATE TABLE media(id INTEGER PRIMARY KEY AUTOINCREMENT,path TEXT NOT NULL UNIQUE,name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,created_at TEXT NOT NULL,deleted INTEGER NOT NULL DEFAULT 0);');
$seed=json_decode(file_get_contents(__DIR__.'/seed.json'),true,512,JSON_THROW_ON_ERROR);$q=$pdo->prepare('INSERT INTO documents(name,value,updated_at) VALUES(?,?,?)');foreach($seed as $name=>$value)$q->execute([$name,json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),gmdate('c')]);
$q=$pdo->prepare('INSERT INTO media(path,name,mime,size,created_at) VALUES(?,?,?,?,?)');$files=new RecursiveIteratorIterator(new RecursiveDirectoryIterator(\NL\root().'/assets',FilesystemIterator::SKIP_DOTS));$finfo=new finfo(FILEINFO_MIME_TYPE);foreach($files as $file){$path=$file->getPathname();if(!preg_match('/\.(jpg|jpeg|png|webp|gif|avif|svg|pdf|mp4)$/i',$path))continue;$url='/assets/'.substr($path,strlen(\NL\root().'/assets/'));$q->execute([$url,$file->getFilename(),$finfo->file($path),$file->getSize(),gmdate('c')]);}
file_put_contents($dir.'/setup.json',json_encode(['hash'=>$hash,'expires'=>time()+7*86400]));chmod($dir.'/setup.json',0600);chmod($dir.'/cms.sqlite',0600);file_put_contents($dir.'/.htaccess',"Require all denied\n");echo "Установка завершена. Первый вход создаётся только по одноразовой ссылке.\n";
